<template><div class="fade-in"><div class="page-header"><h2>QUẢN LÝ CỬA HÀNG</h2><el-button type="primary" @click="open()">Thêm sản phẩm</el-button></div><el-tabs v-model="tab" @tab-change="load">
<el-tab-pane label="Sản phẩm" name="products"><el-table :data="products"><el-table-column prop="id" label="ID" width="70"/><el-table-column label="Sản phẩm" min-width="220"><template #default="{row}"><b>{{row.name}}</b><div class="muted">{{cat(row.category)}} · {{row.brand}}</div></template></el-table-column><el-table-column label="Giá"><template #default="{row}">{{money(row.salePrice||row.price)}}</template></el-table-column><el-table-column prop="stock" label="Tồn kho"/><el-table-column label="Trạng thái"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'Đang bán':'Ngừng bán'}}</el-tag></template></el-table-column><el-table-column label="Thao tác" width="190"><template #default="{row}"><el-button size="small" @click="open(row)">Sửa</el-button><el-button v-if="row.active" size="small" type="danger" plain @click="hide(row)">Ngừng bán</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="Đơn hàng" name="orders"><el-table :data="orders"><el-table-column prop="id" label="Đơn" width="70"/><el-table-column label="Khách hàng" min-width="180"><template #default="{row}">{{row.userName}}<div class="muted">{{row.userEmail}}</div></template></el-table-column><el-table-column label="Sản phẩm" min-width="240"><template #default="{row}">{{row.items.map(i=>`${i.productName} × ${i.quantity}`).join(', ')}}</template></el-table-column><el-table-column label="Tổng"><template #default="{row}">{{money(row.total)}}</template></el-table-column><el-table-column label="Trạng thái" width="180"><template #default="{row}"><el-select :model-value="row.status" :disabled="!next(row.status).length" @change="s=>changeStatus(row,s)"><el-option :label="status(row.status)" :value="row.status"/><el-option v-for="s in next(row.status)" :key="s" :label="status(s)" :value="s"/></el-select></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="dialog" :title="form.id?'Sửa sản phẩm':'Thêm sản phẩm'" width="620"><el-form label-position="top"><div class="grid-2"><el-form-item label="Tên"><el-input v-model="form.name"/></el-form-item><el-form-item label="Danh mục"><el-select v-model="form.category"><el-option label="Thực phẩm bổ sung" value="SUPPLEMENT"/><el-option label="Đồ ăn" value="FOOD"/><el-option label="Dụng cụ" value="EQUIPMENT"/></el-select></el-form-item><el-form-item label="Thương hiệu"><el-input v-model="form.brand"/></el-form-item><el-form-item label="Ảnh URL"><el-input v-model="form.imageUrl"/></el-form-item><el-form-item label="Giá"><el-input-number v-model="form.price" :min="0"/></el-form-item><el-form-item label="Giá khuyến mãi"><el-input-number v-model="form.salePrice" :min="0"/></el-form-item><el-form-item label="Tồn kho"><el-input-number v-model="form.stock" :min="0"/></el-form-item><el-form-item label="Mục tiêu phù hợp"><el-input v-model="form.suitableGoals" placeholder="MUSCLE_GAIN,WEIGHT_LOSS"/></el-form-item></div><el-form-item label="Mô tả"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">Hủy</el-button><el-button type="primary" @click="save">Lưu</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{adminShopAPI}from'@/api';import{ElMessageBox,ElMessage}from'element-plus';const tab=ref('products'),products=ref([]),orders=ref([]),dialog=ref(false);const blank=()=>({name:'',category:'SUPPLEMENT',brand:'',description:'',imageUrl:'',price:0,salePrice:null,stock:0,suitableGoals:'',active:true});const form=ref(blank());const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(v||0),cat=v=>({SUPPLEMENT:'Thực phẩm bổ sung',FOOD:'Đồ ăn',EQUIPMENT:'Dụng cụ'})[v],status=v=>({PENDING_PAYMENT:'Chờ thanh toán',PAID:'Đã thanh toán',PREPARING:'Đang chuẩn bị',SHIPPING:'Đang giao',DELIVERED:'Đã giao',COMPLETED:'Hoàn thành',CANCELLED:'Đã hủy',EXPIRED:'Hết hạn'})[v]||v;const transitions={PAID:['PREPARING'],PREPARING:['SHIPPING'],SHIPPING:['DELIVERED'],DELIVERED:['COMPLETED']};const next=s=>transitions[s]||[];async function load(){if(tab.value==='products')products.value=(await adminShopAPI.products()).data||[];else orders.value=(await adminShopAPI.orders()).data||[]}function open(p){form.value=p?{...p}:blank();dialog.value=true}async function save(){form.value.id?await adminShopAPI.update(form.value.id,form.value):await adminShopAPI.create(form.value);dialog.value=false;ElMessage.success('Đã lưu sản phẩm');load()}async function hide(p){await ElMessageBox.confirm('Ngừng bán sản phẩm này? Lịch sử đơn hàng vẫn được giữ.','Xác nhận');await adminShopAPI.hide(p.id);load()}async function changeStatus(o,s){if(s===o.status)return;await adminShopAPI.status(o.id,s);ElMessage.success('Đã cập nhật trạng thái');load()}onMounted(load);</script>
